1	<?php
2	
3	/**
4	 * nb_works 테이블의 모든 이미지(jpg/jpeg/png/gif)를 webp 로 변환하고
5	 * DB 컬럼 값을 .webp 파일명으로 갱신한 뒤 원본을 삭제하는 1회성 마이그레이션.
6	 *
7	 * 사용법:
8	 *   php scripts/migrate-works-to-webp.php --dry-run
9	 *   php scripts/migrate-works-to-webp.php
10	 *   php scripts/migrate-works-to-webp.php --id=1115
11	 *   php scripts/migrate-works-to-webp.php --limit=10
12	 *
13	 * 안전 장치:
14	 *   - DB UPDATE 가 성공한 뒤에만 원본 unlink (실패 시 데이터 손실 방지)
15	 *   - 컬럼 1건 단위 트랜잭션 — 일부 실패가 다른 항목에 전파되지 않음
16	 *   - svg/ico/webp 는 skip
17	 *   - 디스크에 파일 없으면 컬럼 그대로 두고 skip
18	 */
19	
20	if (PHP_SAPI !== 'cli') {
21	    http_response_code(403);
22	    exit('CLI only.' . PHP_EOL);
23	}
24	
25	ini_set('memory_limit', '1024M');
26	
27	// GD는 width*height*4 바이트를 RAM에 올리고, 인코딩 시 동등한 양을 다시 사용한다.
28	// 16MP 초과 이미지는 1024M 한도 내에서도 fatal 위험 — 변환 시도 자체를 skip.
29	const MAX_PIXELS = 16_000_000;
30	
31	$args = $argv ?? [];
32	$isDryRun = in_array('--dry-run', $args, true);
33	$onlyId = null;
34	$limit = null;
35	foreach ($args as $a) {
36	    if (preg_match('/^--id=(\d+)$/', $a, $m)) {
37	        $onlyId = (int) $m[1];
38	    } elseif (preg_match('/^--limit=(\d+)$/', $a, $m)) {
39	        $limit = (int) $m[1];
40	    }
41	}
42	
43	$projectRoot = null;
44	$dir = __DIR__;
45	while ($dir !== dirname($dir)) {
46	    if (is_file($dir . '/vendor/autoload.php')) {
47	        $projectRoot = $dir;
48	        break;
49	    }
50	    $dir = dirname($dir);
51	}
52	if ($projectRoot === null) {
53	    fwrite(STDERR, 'ERROR: project root not found' . PHP_EOL);
54	    exit(1);
55	}
56	
57	require_once $projectRoot . '/vendor/autoload.php';
58	require_once $projectRoot . '/config/setup.php';
59	
60	use Core\ImageProcessor;
61	use Database\DB;
62	
63	$worksDir = $projectRoot . '/uploads/works';
64	if (!is_dir($worksDir)) {
65	    fwrite(STDERR, 'ERROR: uploads/works not found at: ' . $worksDir . PHP_EOL);
66	    exit(1);
67	}
68	
69	$imageColumns = ['thumb_image', 'file_attach1', 'file_attach2', 'file_attach3', 'file_attach4', 'file_attach5'];
70	$convertible = ImageProcessor::CONVERTIBLE;
71	$skipExt = array_merge($convertible === [] ? [] : [], ['svg', 'ico', 'webp']);
72	
73	$pdo = DB::getInstance();
74	
75	$sql = 'SELECT `id`, `' . implode('`, `', $imageColumns) . '` FROM `nb_works`';
76	if ($onlyId !== null) {
77	    $sql .= ' WHERE `id` = ' . $onlyId;
78	}
79	$sql .= ' ORDER BY `id` ASC';
80	if ($limit !== null) {
81	    $sql .= ' LIMIT ' . $limit;
82	}
83	
84	$stmt = $pdo->query($sql);
85	$rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);
86	
87	$counts = [
88	    'rows' => 0,
89	    'cells_total' => 0,
90	    'cells_empty' => 0,
91	    'cells_skipped_ext' => 0,
92	    'cells_skipped_too_large' => 0,
93	    'cells_missing_file' => 0,
94	    'cells_converted' => 0,
95	    'cells_failed_convert' => 0,
96	    'cells_failed_db' => 0,
97	    'bytes_saved' => 0,
98	];
99	
100	echo ($isDryRun ? '[DRY-RUN] ' : '') . 'works rows to process: ' . count($rows) . PHP_EOL;
101	
102	foreach ($rows as $row) {
103	    $counts['rows']++;
104	    $workId = (int) $row['id'];
105	
106	    foreach ($imageColumns as $col) {
107	        $counts['cells_total']++;
108	        $value = trim((string) ($row[$col] ?? ''));
109	
110	        if ($value === '') {
111	            $counts['cells_empty']++;
112	            continue;
113	        }
114	
115	        $ext = strtolower(pathinfo($value, PATHINFO_EXTENSION));
116	        if (in_array($ext, $skipExt, true) || !in_array($ext, $convertible, true)) {
117	            $counts['cells_skipped_ext']++;
118	            continue;
119	        }
120	
121	        $absOriginal = $worksDir . '/' . $value;
122	        if (!is_file($absOriginal)) {
123	            fwrite(STDERR, sprintf("[missing] id=%d %s='%s' (file not on disk)\n", $workId, $col, $value));
124	            $counts['cells_missing_file']++;
125	            continue;
126	        }
127	
128	        // 16MP 초과는 변환 자체가 fatal 위험 → DB·파일 그대로 두고 skip.
129	        $imgSize = @getimagesize($absOriginal);
130	        if (is_array($imgSize) && isset($imgSize[0], $imgSize[1])
131	            && ($imgSize[0] * $imgSize[1]) > MAX_PIXELS) {
132	            fwrite(STDERR, sprintf("[too-large] id=%d %s='%s' (%dx%d)\n",
133	                $workId, $col, $value, $imgSize[0], $imgSize[1]));
134	            $counts['cells_skipped_too_large']++;
135	            continue;
136	        }
137	
138	        $webpName = preg_replace('/\.[^.]+$/', '.webp', $value);
139	        $absWebp = $worksDir . '/' . $webpName;
140	
141	        if ($isDryRun) {
142	            echo sprintf("[dry-run] id=%d %s: '%s' -> '%s'\n", $workId, $col, $value, $webpName);
143	            $counts['cells_converted']++;
144	            continue;
145	        }
146	
147	        $originalSize = (int) @filesize($absOriginal);
148	        fwrite(STDOUT, sprintf("[try] id=%d %s='%s' (%dKB)\n", $workId, $col, $value, (int) round($originalSize / 1024)));
149	        @ob_flush();
150	        @flush();
151	
152	        $existedBefore = is_file($absWebp);
153	        $ok = ImageProcessor::makeWebpSibling($absOriginal);
154	        if (!$ok || !is_file($absWebp) || filesize($absWebp) === 0) {
155	            fwrite(STDERR, sprintf("[CONVERT-FAIL] id=%d %s='%s'\n", $workId, $col, $value));
156	            $counts['cells_failed_convert']++;
157	            // 변환 실패로 생긴 0바이트 잔존 파일이 있다면 정리 (이전부터 존재하던 webp 는 보존)
158	            if (!$existedBefore && is_file($absWebp) && filesize($absWebp) === 0) {
159	                @unlink($absWebp);
160	            }
161	            continue;
162	        }
163	
164	        try {
165	            $update = $pdo->prepare('UPDATE `nb_works` SET `' . $col . '` = :val WHERE `id` = :id');
166	            $update->execute([':val' => $webpName, ':id' => $workId]);
167	        } catch (\Throwable $e) {
168	            fwrite(STDERR, sprintf("[DB-FAIL] id=%d %s='%s': %s\n", $workId, $col, $value, $e->getMessage()));
169	            $counts['cells_failed_db']++;
170	            if (!$existedBefore && is_file($absWebp)) {
171	                @unlink($absWebp);
172	            }
173	            continue;
174	        }
175	
176	        @unlink($absOriginal);
177	        $counts['cells_converted']++;
178	        $counts['bytes_saved'] += max(0, $originalSize - (int) @filesize($absWebp));
179	        echo sprintf("[ok] id=%d %s: '%s' -> '%s'\n", $workId, $col, $value, $webpName);
180	    }
181	}
182	
183	echo PHP_EOL;
184	echo "--- Summary " . ($isDryRun ? '(DRY-RUN) ' : '') . "---" . PHP_EOL;
185	echo "Rows processed       : {$counts['rows']}" . PHP_EOL;
186	echo "Cells total          : {$counts['cells_total']}" . PHP_EOL;
187	echo "  empty              : {$counts['cells_empty']}" . PHP_EOL;
188	echo "  skipped (svg/ico/webp): {$counts['cells_skipped_ext']}" . PHP_EOL;
189	echo "  skipped (too large): {$counts['cells_skipped_too_large']}" . PHP_EOL;
190	echo "  missing on disk    : {$counts['cells_missing_file']}" . PHP_EOL;
191	echo "  converted          : {$counts['cells_converted']}" . PHP_EOL;
192	echo "  convert failed     : {$counts['cells_failed_convert']}" . PHP_EOL;
193	echo "  db update failed   : {$counts['cells_failed_db']}" . PHP_EOL;
194	echo "Bytes saved          : " . number_format($counts['bytes_saved']) . " (" . round($counts['bytes_saved'] / 1024 / 1024, 2) . " MB)" . PHP_EOL;
195	
196	exit(($counts['cells_failed_convert'] + $counts['cells_failed_db']) > 0 ? 1 : 0);
