8	class ImageProcessor
9	{
10	    public const MAX_WIDTH = 2560;
11	    public const WEBP_QUALITY = 82;
12	    public const CONVERTIBLE = ['jpg', 'jpeg', 'png', 'gif'];
13	    public const MEMORY_LIMIT = '1024M';
14	
15	    /**
16	     * 업로드된 원본 이미지 옆에 .webp sibling 을 생성한다.
17	     * 원본은 그대로 둔다. 실패해도 예외를 삼켜서 업로드 플로우를 깨뜨리지 않는다.
18	     */
19	    public static function makeWebpSibling(string $absolutePath): bool
20	    {
21	        if (!is_file($absolutePath)) {
22	            return false;
23	        }
24	
25	        $ext = strtolower(pathinfo($absolutePath, PATHINFO_EXTENSION));
26	        if (!in_array($ext, self::CONVERTIBLE, true)) {
27	            return false;
28	        }
29	
30	        $webpPath = preg_replace('/\.[^.]+$/', '.webp', $absolutePath);
31	
32	        // GD 의 비트맵 디코딩은 압축된 jpg 크기보다 훨씬 더 큰 메모리를 소모한다.
33	        // 기본 128M 으로는 큰 이미지에서 OOM 으로 silent fail 하므로 일시 상향.
34	        $previousLimit = ini_get('memory_limit');
35	        @ini_set('memory_limit', self::MEMORY_LIMIT);
36	
37	        try {
38	            $image = Image::load($absolutePath);
39	
40	            $size = @getimagesize($absolutePath);
41	            if (is_array($size) && isset($size[0]) && $size[0] > self::MAX_WIDTH) {
42	                $image->width(self::MAX_WIDTH);
43	            }
44	
45	            $image->format('webp')
46	                ->quality(self::WEBP_QUALITY)
47	                ->save($webpPath);
48	
49	            return is_file($webpPath);
50	        } catch (Throwable $e) {
51	            error_log('[ImageProcessor] webp sibling failed for ' . $absolutePath . ': ' . $e->getMessage());
52	            return false;
53	        } finally {
54	            if ($previousLimit !== false) {
55	                @ini_set('memory_limit', $previousLimit);
56	            }
57	        }
58	    }
59	
60	    /**
61	     * 주어진 이미지 경로의 .webp sibling 을 삭제한다. 원본은 건드리지 않는다.
62	     * imageDelete() 에서 호출되어 삭제 시 동반 정리를 담당.
63	     */
64	    public static function deleteWebpSibling(string $absolutePath): bool
65	    {
66	        $ext = strtolower(pathinfo($absolutePath, PATHINFO_EXTENSION));
67	        if (!in_array($ext, self::CONVERTIBLE, true)) {
68	            return false;
69	        }
70	
71	        $webpPath = preg_replace('/\.[^.]+$/', '.webp', $absolutePath);
72	        if (is_file($webpPath)) {
73	            return @unlink($webpPath);
74	        }
75	
76	        return false;
77	    }
78	}

